{
  "title": "The Mirrorglass Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surfaces in a ruined plaza.",
      "visual_description": "A cracked cobblestone plaza littered with fallen royal banners. The glass diver rises from a shattered window pool, helmet gleaming.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfurls a map under a broken arch.",
      "visual_description": "Mara crouches beneath a crumbling stone arch, ink-stained coat brushing rubble as she traces a path on parchment.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning from a ledge.",
      "visual_description": "An old stone ledge holds the oracle lamp, its single flame-eye darting as it whispers of cursed towers ahead.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through a collapsed market.",
      "visual_description": "The small metal fox picks its way over toppled stalls, key-wind tail ticking, blue glass eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks a doorway, dozing.",
      "visual_description": "A ledger book as pillow, stamped papers stuck to sleeves, the sleeping tax collector snores in an arched doorway.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver peers through a cursed tower window.",
      "visual_description": "The glass diver presses helmet to a grimy window, seeing distorted shadows inside the tower.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara reads a faded inscription on the castle gate.",
      "visual_description": "Mara runs fingers over carved stone letters on the massive castle gates, compass swinging.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals a hidden path through rubble.",
      "visual_description": "The lamp's glow casts a long shadow pointing to a narrow alley choked with broken stone.",
      "characters": ["oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Armored patrols march past a collapsed fountain.",
      "visual_description": "Marching figures in rusted armor pass by a dry fountain, their footsteps echoing.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through a mirror inside a ruined hall.",
      "visual_description": "Inside a roofless hall, the glass diver steps into a tall mirror and emerges from another across the room.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector is dragged to a magic door.",
      "visual_description": "Tin fox tugs the collector's sleeve while Mara and glass diver push open a glowing door inscribed with runes.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp warns of a trap behind the magic door.",
      "visual_description": "Beyond the door, a pit of shimmering light awaits; the lamp's eye widens.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox disarms the trap with a quick paw.",
      "visual_description": "The metal fox inserts its tail into a floor socket; gears click and the pit seals.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The group finds a frightened cat cowering behind a tapestry.",
      "visual_description": "Torn royal tapestry sways; a small cat hides behind it, eyes wide.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector wakes briefly to stamp a document.",
      "visual_description": "Collector sits up, stamps a scrap of paper, then slumps back asleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver leads the way to the bridge.",
      "visual_description": "Glass diver points toward a stone bridge spanning a chasm, broken city behind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge trembles as patrols approach from behind.",
      "visual_description": "The bridge groans underfoot; distant armored figures appear at the far end of the street.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge into mist.",
      "visual_description": "All cross the bridge as mist swallows the ruins; the glass diver looks back once.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

